# Velocity hotfix: e3eff667 -> b49e3d53 (offline sync, MC 26.2 build fixes)
# Usage: powershell -ExecutionPolicy Bypass -File .\velocity-hotfix.ps1
#        powershell -ExecutionPolicy Bypass -File .\velocity-hotfix.ps1 -Root "D:\path\to\SkyCore 26.2"
param(
    [string]$Root = "C:\Users\User\Desktop\SWeltek\GodWeer\SkyCore 26.2"
)

$ErrorActionPreference = "Stop"
if (-not (Test-Path (Join-Path $Root "src\main\java\net\skycore\client"))) {
    Write-Host "ERROR: $Root is not the SkyCore 26.2 project root." -ForegroundColor Red
    exit 1
}

$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backup = Join-Path $Root ".velocity-backup-$stamp"

$payload = @(
    [pscustomobject]@{ Path = "src/main/java/net/skycore/client/combat/velocity/NuclearVelocity.java"; Sha256 = "e6cea89ba473df14d9dc0f5c4c0ffbec424988e7a2ec6c3359183776e57c58ca"; Data = "" }
    [pscustomobject]@{ Path = "src/main/java/net/skycore/client/combat/velocity/PhobiaVelocity.java"; Sha256 = "6813bf86b6e9464cb7c59b2496e1c3d102dce428163a71379094a468565e920f"; Data = "" }
    [pscustomobject]@{ Path = "src/main/java/net/skycore/client/combat/velocity/ReleonVelocity.java"; Sha256 = "43dbc72f635e1515ceb5f3bed55889387446627abbf6f58ae488dfc783afd81b"; Data = "" }
    [pscustomobject]@{ Path = "src/main/java/net/skycore/client/combat/velocity/SadnesVelocity.java"; Sha256 = "a1e4aaa17f38f26ad5e9fa81c26d09d5030778d17989888f906ee67def15622e"; Data = "" }
    [pscustomobject]@{ Path = "src/main/java/net/skycore/client/combat/velocity/WildVelocity.java"; Sha256 = "fe5413a23a869d60b8f570753fbbaabc3f3b8174a6ccd078efc34bd20c80522c"; Data = "" }
    [pscustomobject]@{ Path = "src/main/java/net/skycore/client/combat/velocity/PrivateVelocity.java"; Sha256 = "087b3f1d946a643c680e71953ea98e5a9be07bc2dbd4fbc4cdcf5618daa87970"; Data = "" }
    [pscustomobject]@{ Path = "src/main/java/net/skycore/client/module/movement/VelocityModule.java"; Sha256 = "8f916737cd5c50aa47550aa7568d0bab0606cbbb76fac71fb4775e675a8a7650"; Data = "" }
    [pscustomobject]@{ Path = "docs/VELOCITY.md"; Sha256 = "a6d18e5b1181e62279de62c1580a608c87f7a9921a4a5682325e76bc42269c7b"; Data = "" }
)

$failed = 0
foreach ($item in $payload) {
    $target = Join-Path $Root ($item.Path -replace "/", "\")
    $bytes = [Convert]::FromBase64String($item.Data)
    $sha = [BitConverter]::ToString([Security.Cryptography.SHA256]::Create().ComputeHash($bytes)).Replace("-", "").ToLower()
    if ($sha -ne $item.Sha256) {
        Write-Host ("CHECKSUM FAILED in payload: " + $item.Path) -ForegroundColor Red
        $failed++
        continue
    }
    $dir = Split-Path -Parent $target
    if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
    if (Test-Path $target) {
        $relBackup = Join-Path $backup (Split-Path -Parent ($item.Path -replace "/", "\"))
        if (-not (Test-Path $relBackup)) { New-Item -ItemType Directory -Path $relBackup -Force | Out-Null }
        Copy-Item -LiteralPath $target -Destination (Join-Path $relBackup (Split-Path -Leaf $target)) -Force
    }
    [IO.File]::WriteAllBytes($target, $bytes)
    Write-Host ("OK   " + $item.Path) -ForegroundColor Green
}

if ($failed -gt 0) {
    Write-Host "$failed file(s) failed, nothing else changed." -ForegroundColor Red
    exit 1
}
Write-Host ""
Write-Host "All 8 files written." -ForegroundColor Cyan
if (Test-Path $backup) { Write-Host "Originals backed up to: $backup" }
Write-Host "Next: cd `"$Root`"; .\gradlew.bat build --no-daemon" -ForegroundColor Cyan
